def run_to_seed(I,seedval):
    H=len(I);W=len(I[0]); out={}; seen=set()
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    for r in range(H):
        for c in range(W):
            if I[r][c]!=0: continue
            hit=False
            for dd,dc in dirs:
                x,y=r+dd,c+dc; clear=True
                while 0<=x<H and 0<=y<W:
                    v=I[x][y]
                    if v==seedval: hit=True; break
                    if v!=0: clear=False; break
                    x+=dd; y+=dc
                # treat hit with clear path
                if hit or clear: hit=True
            out[(r,c)]=hit
    return out

